assert len(specs)==25
by_current={r['pilot_name']:r for r in current['cast']}
by_story={r['name']:r for r in story['characters']}
rows=[]
for name,hp,en,armor,mobility,move,role,powers,usage,ability in specs:
 c=by_current[name];s=by_story[name]
 initial_grade=0 if s['playable']<=8 else 2 if s['playable']<=20 else 3 if s['playable']<=26 else 4
 weapons=[]
 for w in c['weapons']:
  kept=w['name'] in powers
  weapons.append({'name':w['name'],'current_power':w['power'],'proposed_power':powers.get(w['name']),
                  'original_weapon_key':w['key'],'status':'기본 무장 유지·조정' if kept else '기본 무장에서 제외; 통상 상태이상 하나는 추후 검토'})
 assert set(powers)<={w['name'] for w in c['weapons']},(name,'nonexistent weapon')
 rows.append({'name':name,'robot':s['robot'],'playable_chapter':s['playable'],'role':role,
              'current_base':{k:c[k] for k in ['hp','en','armor','mobility','move']},
              'proposed_base':dict(hp=hp,en=en,armor=armor,mobility=mobility,move=move),
              'current_max_weapon_power':max(w['power'] for w in c['weapons']),
              'proposed_max_weapon_power':max(powers.values()),'initial_upgrade_grade':initial_grade,
              'usage':usage,'ability_policy':ability,'weapons':weapons})

